import type { ClientRuntimeConfig } from '../../configs/runtime-client';

export interface ClientConfig extends ClientRuntimeConfig {
  // TODO If we have configs generated by client?
}

function getConfig() {
  if (typeof window === 'undefined') {
    return {};
  }

  return window['CLIENT_CONFIG'];
}

// 默认的配置
const DEFAULT_CLIENT_CONFIG = {
  appEnv: 'production',
  appEdition: 'createra',
};

export const clientConfig: ClientConfig = Object.assign(
  DEFAULT_CLIENT_CONFIG,
  getConfig(),
);
